void fir(data_t *in, data_t *out, int n) {
  for (int i = 0; i < n; i++) {
    #pragma HLS pipeline II=1
    acc_t acc = 0;
    for (int t = 0; t < TAPS; t++) {
      #pragma HLS unroll
      acc += coeff[t] * in[i - t];
    }
    out[i] = acc;
  }
}

void fir(data_t *in, data_t *out, int n) {
  #pragma HLS array_partition variable=coeff type=complete dim=1
  for (int i = 0; i < n; i++) {
    #pragma HLS pipeline II=1
    acc_t acc = 0;
    for (int t = 0; t < TAPS; t++) {
      #pragma HLS unroll                 // full unroll: TAPS multipliers
      acc += coeff[t] * in[i - t];
    }
    out[i] = acc;
  }
}

