void vadd(const int *a, const int *b, int *c, int n) {
  #pragma HLS interface mode=m_axi port=a bundle=gmem0 offset=slave depth=1024
  #pragma HLS interface mode=m_axi port=b bundle=gmem1 offset=slave depth=1024
  #pragma HLS interface mode=m_axi port=c bundle=gmem0 offset=slave depth=1024
  #pragma HLS interface mode=s_axilite port=n      bundle=control
  #pragma HLS interface mode=s_axilite port=return bundle=control

  for (int i = 0; i < n; i++) {
    #pragma HLS pipeline II=1
    c[i] = a[i] + b[i];
  }
}

