tools.example:
void top(const data_t *in, data_t *out, int n) {
  #pragma HLS dataflow
  hls::stream<data_t> s1("s1"), s2("s2");
  #pragma HLS stream variable=s1 depth=64
  #pragma HLS stream variable=s2 depth=64

  read_input(in, s1, n);   // stage 1
  compute(s1, s2, n);      // stage 2
  write_output(s2, out, n); // stage 3
}

// Small helper: inline so it is scheduled with the caller
static data_t saturate(acc_t v) {
  #pragma HLS inline
  return (v > MAX) ? (data_t)MAX : (data_t)v;
}

// Dataflow stage: must keep its boundary
void compute(hls::stream<data_t> &in, hls::stream<data_t> &out, int n) {
  #pragma HLS inline off
  for (int i = 0; i < n; i++) {
    #pragma HLS pipeline II=1
    out.write(saturate(in.read() * GAIN));
  }
}

void fir(data_t *in, data_t *out, int n) {
  loop_samples:
  for (int i = 0; i < n; i++) {
    #pragma HLS loop_tripcount min=64 max=4096 avg=1024
    #pragma HLS pipeline II=1
    out[i] = process(in[i]);
  }
}

void control_step(const data_t *x, data_t *y) {
  #pragma HLS latency max=16
  // scheduler must complete this block within 16 cycles
  for (int i = 0; i < N; i++) {
    #pragma HLS unroll
    y[i] = gain[i] * x[i];
  }
}

